import {state,DEMO} from '../../core/state.js?v=7d9a7701690b';
import {api,projectQuery,exportFile} from '../../core/api.js?v=7d9a7701690b';
import {refresh} from '../../core/events.js?v=7d9a7701690b';
import {esc,heading,panel,btn,select,textarea,field,formEnd,modal,closeModal,toast,empty} from '../../core/ui.js?v=7d9a7701690b';
let data={runs:[],claimed:[],conflicts:[]},task=null,adjudicating=false;
export async function load(){if(!DEMO)data=await api('studio/budget'+projectQuery());}
export function render(){if(DEMO)return empty('Cần bản native','Không tạo thực nghiệm giả trong demo tĩnh.');return heading('Kiểm tra theo ngân sách','Grouping local–API nhiều lớp. P3 đo proxy thay đổi nhãn/thời gian hoạt động.',state.workspace.project.can_manage?btn('Tạo phiên','budget:create','primary'):'')+`<div class="info-banner">Đồng hồ cộng tối đa 20 giây giữa các heartbeat. Ẩn tab sẽ tạm dừng; mất mạng được ghi thời gian chờ. Đây là phép đo vận hành, không phải thời gian lao động chuẩn hóa.</div>`+panel('Mẫu đang làm',data.claimed.map(t=>`<p>#${t.comment_id} ${btn('Tiếp tục lượt mù','budget:open','primary','',`data-id="${t.id}"`)}</p>`).join('')||'<p>Chưa nhận mẫu.</p>')+panel('Phiên đã chốt quần thể',data.runs.map(r=>`<article class="review-run"><b>#${r.id} · ${esc(r.policy)} · ${esc(r.state)}</b><p>${Math.round(r.used_seconds)}/${r.budget_seconds}s · ${r.completed} xong · ${r.conflicts} cần phân xử</p>${btn('Nhận mẫu mù','budget:claim','sm','',`data-id="${r.id}"`)}${state.workspace.project.can_manage?btn(r.state==='paused'?'Tiếp tục phiên':'Tạm dừng phiên','budget:control','sm','',`data-id="${r.id}" data-mode="${r.state==='paused'?'resume':'pause'}"`)+btn('Tải báo cáo JSON','budget:report','sm','',`data-id="${r.id}"`)+btn('Replay nhiều seed','budget:replay','sm','',`data-id="${r.id}"`):''}</article>`).join(''))+panel('Phân xử người thứ ba',data.conflicts.map(t=>`<p>${esc(t.text)} ${btn('Phân xử','budget:gold','sm','',`data-id="${t.id}"`)}</p>`).join('')||'<p>Không có mẫu phù hợp.</p>');}
function draw(){const labels=task.labels.map(l=>[l.key,l.name]);modal(adjudicating?'Phân xử người thứ ba':'Kiểm tra mù',`<p>${esc(task.text)}</p><p>${esc(task.context||'')}</p>${adjudicating?`<p>Lượt đầu: ${esc(task.first_label)} · Lượt mù: ${esc(task.blind_label)}</p>`:'<p>Không hiển thị dự đoán, nhóm mẫu hay nhãn tham chiếu.</p>'}${btn('Tạm dừng','budget:pause','sm')}${btn('Tiếp tục','budget:resume','sm')}<form data-submit="budget:decision">${select('label','Nhãn độc lập',[['','— Chọn nhãn —'],...labels],'')}${textarea('note','Lý do')}${formEnd('Nộp')}</form>`);}
export async function action(name,el){
 if(name==='create'){const d=await api('studio/collaboration'+projectQuery());modal('Phiên local–API',`<form data-submit="budget:create">${select('batch_id','Lượt dự đoán',d.runs.map(r=>[r.id,'#'+r.id]),d.runs[0]?.id)}${select('policy','Policy',[['random','P0 ngẫu nhiên'],['fixed','P1 bất đồng trước'],['fixed_explore','P2 bất đồng + 20% thăm dò đồng thuận'],['adaptive','P3 proxy thay đổi nhãn/thời gian']],'fixed_explore')}${field('minutes','Ngân sách phút',30,'number','min="1" max="600"')}${field('seed','Seed',42,'number','min="0"')}${formEnd('Chốt quần thể')}</form>`);return;}
 if(name==='claim'){const r=await api(`runs/${el.dataset.id}/claim`,{});task=r.task;adjudicating=false;draw();return;}
 if(name==='open'){task=data.claimed.find(t=>String(t.id)===el.dataset.id);adjudicating=false;draw();return;}
 if(name==='gold'){const r=await api(`tasks/${el.dataset.id}/adjudicate`,{action:'open'});task=r.task;adjudicating=true;draw();return;}
 if(name==='pause'||name==='resume'){await clock(name);toast(name==='pause'?'Đã dừng đồng hồ':'Đã tiếp tục đồng hồ');return;}
 if(name==='control'){await api(`studio/budget/runs/${el.dataset.id}/control`,{action:el.dataset.mode});await refresh();return;}
 if(name==='report'||name==='replay')await exportFile(`studio/budget/runs/${el.dataset.id}/report?download=1${name==='replay'?'&replay=1&seeds=7,42,103':''}`,`review-${el.dataset.id}.json`);
}
export async function submit(name,f){const v=Object.fromEntries(new FormData(f));if(name==='create')await api('runs',{...v,project:state.workspace.project.id,grouping_strategy:'local_api',minutes:Number(v.minutes),seed:Number(v.seed)});else{await api(`tasks/${task.id}/${adjudicating?'adjudicate':'submit'}`,v);task=null;}closeModal();await refresh();}
async function clock(action){const current=task;if(!current)return;const value=await api(`studio/budget/tasks/${current.id}/clock`,{action});current.clock=value.clock;}
setInterval(()=>{if(task&&state.route==='budget'&&document.querySelector('[role=dialog]')&&!document.hidden&&task.clock?.state==='active')clock('heartbeat').catch(()=>{});},10000);
document.addEventListener('visibilitychange',()=>{if(task&&document.hidden)clock('pause').catch(()=>{});});
document.addEventListener('click',e=>{if(task&&e.target.closest('[data-action="ui:close"]')){clock('pause').catch(()=>{});task=null;}});
